<script setup>
import PortalLayout from '@/Layouts/PortalLayout.vue'; import { Head,Link,router } from '@inertiajs/vue3'; const props=defineProps({product:{type:Object,required:true},plan:{type:Object,required:true}}); const remove=()=>{if(window.confirm(`Delete ${props.plan.name}?`))router.delete(route('admin.plans.destroy',props.plan.id));};
</script>
<template><Head :title="plan.name"/><PortalLayout area="Administration"><template #navigation><Link :href="route('admin.dashboard')" class="block rounded-lg px-3 py-2 text-slate-600">Overview</Link><Link :href="route('admin.products.index')" class="block rounded-lg bg-cyan-50 px-3 py-2 font-medium text-cyan-800">Products</Link></template><div v-if="$page.props.flash.success" class="success-message mb-5">{{ $page.props.flash.success }}</div><div class="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><div class="flex flex-col gap-4 sm:flex-row sm:justify-between"><div><Link :href="route('admin.products.plans.index',product.slug)" class="text-sm font-bold text-cyan-700">← {{ product.name }} plans</Link><h1 class="mt-2 text-3xl font-bold">{{ plan.name }}</h1><p class="mt-2 text-slate-600">{{ plan.description }}</p></div><div class="flex gap-2"><Link :href="route('admin.plans.edit',plan.id)" class="form-button">Edit</Link><button class="rounded-xl border border-red-200 px-5 py-3 font-bold text-red-700" @click="remove">Delete</button></div></div><dl class="mt-8 grid gap-4 rounded-xl bg-slate-50 p-5 sm:grid-cols-3"><div><dt class="text-xs uppercase text-slate-500">Price</dt><dd class="mt-1 font-bold">{{ plan.billing_cycle==='custom'?'Custom':`${plan.currency} ${plan.price}` }}</dd></div><div><dt class="text-xs uppercase text-slate-500">Billing</dt><dd class="mt-1 font-bold">{{ plan.billing_cycle.replace('_',' ') }}</dd></div><div><dt class="text-xs uppercase text-slate-500">Visibility</dt><dd class="mt-1 font-bold">{{ plan.is_public?'Public':'Private' }}</dd></div></dl><div class="mt-8 grid gap-8 md:grid-cols-2"><section><h2 class="text-xl font-bold">Features</h2><ul class="mt-4 space-y-3"><li v-for="feature in plan.features" :key="feature.uuid" class="flex justify-between border-b border-slate-100 pb-2"><span>{{ feature.feature_name }}</span><strong>{{ feature.enabled?(feature.limit_value||'Enabled'):'Disabled' }}</strong></li></ul></section><section><h2 class="text-xl font-bold">Limits</h2><ul class="mt-4 space-y-3"><li v-for="limit in plan.limits" :key="limit.uuid" class="flex justify-between border-b border-slate-100 pb-2"><span>{{ limit.limit_name }}</span><strong>{{ limit.limit_value||'Unlimited' }}</strong></li></ul></section></div></div></PortalLayout></template>
